<?php

namespace App\Commerce;

use Brick\Math\BigDecimal;
use Illuminate\Http\Request;
use MongoDB\BSON\UTCDateTime;

final class Marketing
{
    public function __construct(private readonly CommerceStore $s,private readonly Promotions $promos) {}
    private function name(string $kind): string {return $kind==='campaigns'?'shop_campaigns':'shop_vouchers';}
    public function admin(Request $r,string $chain,string $kind,?string $id=null): array
    {
        $this->s->admin($r,$chain,null,true);if($r->isMethod('get'))return array_map(fn($p)=>CommerceStore::present($p)+['report'=>$this->report($kind,$p)],$this->s->rows($this->name($kind),['chain_id'=>$chain],['id_sort'=>-1],1000));
        $d=$r->validate(['code'=>'required|string|min:3|max:40|regex:/^[A-Za-z0-9_-]+$/','name'=>'required|string|max:160','description'=>'nullable|string|max:3000','banner'=>'nullable|string|max:500|regex:~^/images/[A-Za-z0-9/_.,%\-]+$~','status'=>'required|in:draft,scheduled,active,paused,ended','starts_at'=>'required|date','ends_at'=>'required|date|after:starts_at','kind'=>$kind==='campaigns'?'required|in:percent,fixed,price':'required|in:percent,fixed,freeship','value'=>'required|string|max:20','maximum_discount'=>'nullable|string|max:20','minimum_order'=>'required|string|max:20','minimum_quantity'=>'required|string|max:20','budget'=>'nullable|string|max:20','max_uses'=>'nullable|integer|min:1|max:100000000','per_customer_limit'=>'nullable|integer|min:1|max:1000000','audience'=>'required|in:all,new,vip,dealer,birthday,season','season_key'=>'nullable|string|max:80','product_ids'=>'present|array|max:200','product_ids.*'=>'string|distinct|regex:/^[1-9][0-9]{0,18}$/','category_ids'=>'present|array|max:100','category_ids.*'=>'string|distinct|regex:/^[1-9][0-9]{0,18}$/','branch_ids'=>'present|array|max:100','branch_ids.*'=>'string|distinct|regex:/^[1-9][0-9]{0,18}$/','customer_ids'=>'present|array|max:200','customer_ids.*'=>'string|distinct|regex:/^[1-9][0-9]{0,18}$/','combo'=>'present|array|max:20','combo.*.product_id'=>'required|string|distinct|regex:/^[1-9][0-9]{0,18}$/','combo.*.quantity'=>'required|string|max:20','allow_vouchers'=>'required|boolean','allow_auto'=>'required|boolean','allow_other_vouchers'=>'required|boolean','restore_on_cancel'=>'required|boolean','restore_on_partial_return'=>'required|boolean']);
        $d['code']=mb_strtoupper($d['code']);foreach(['value','minimum_order','maximum_discount','budget'] as $key)if(isset($d[$key]))$d[$key]=(string)CommerceStore::money($d[$key]);$d+=['maximum_discount'=>null,'budget'=>null,'max_uses'=>null,'per_customer_limit'=>null,'season_key'=>null,'description'=>null,'banner'=>null];$d['minimum_quantity']=(string)CommerceStore::quantity($d['minimum_quantity']);if($d['kind']==='percent')abort_unless(BigDecimal::of($d['value'])->isLessThanOrEqualTo(100),422,'Phần trăm không vượt 100.');if($d['audience']==='season')abort_unless(trim($d['season_key']??'')!=='',422,'Cần mã mùa vụ.');foreach($d['combo'] as &$line)$line['quantity']=(string)CommerceStore::quantity($line['quantity']);unset($line);foreach(['starts_at','ends_at'] as $key)$d[$key]=new UTCDateTime(new \DateTimeImmutable($d[$key]));
        return $this->s->transaction(function()use($r,$chain,$kind,$id,$d){$this->s->admin($r,$chain,null,true);$name=$this->name($kind);$old=$id?$this->s->find($name,$id):null;if($id)abort_unless($old&&$old['chain_id']===$chain,404);$same=$this->s->first($name,['chain_id'=>$chain,'code'=>$d['code']]);if(!$id&&$same){abort_unless(($same['input_fingerprint']??null)===CommerceStore::fingerprint($d),409,'Mã ưu đãi đã tồn tại với cấu hình khác.');return CommerceStore::present($same)+['replayed'=>true];}abort_if($same&&$same['_id']!==$id,409,'Mã ưu đãi đã tồn tại.');if($old)abort_if($this->s->first($kind==='campaigns'?'shop_campaign_redemptions':'shop_voucher_redemptions',['promotion_id'=>$id]),409,'Chương trình đã có lịch sử. Chỉ đổi trạng thái hoặc tạo mã mới để giữ snapshot.');
            foreach($d['branch_ids'] as $b){$row=$this->s->identity->find('branches',$b);abort_unless($row&&$row['chain_id']===$chain,422,'Chi nhánh khác chuỗi.');}foreach($d['customer_ids'] as $c)abort_unless($this->s->find('shop_customers',$c),422,'Khách hàng không tồn tại.');$catalog=app(\App\Support\CatalogStore::class);foreach(array_unique(array_merge($d['product_ids'],array_column($d['combo'],'product_id'))) as $pid)abort_unless($catalog->find('products',$pid),422,'Sản phẩm không tồn tại.');foreach($d['category_ids'] as $cat)abort_unless($catalog->find('product_categories',$cat),422,'Danh mục không tồn tại.');
            $data=$d+['chain_id'=>$chain,'input_fingerprint'=>CommerceStore::fingerprint($d)];$row=$old?$this->s->update($name,$old,$data):$this->s->insert($name,$data);if($kind==='vouchers')foreach($d['customer_ids'] as $cid)if(!$this->s->first('shop_voucher_claims',['customer_id'=>$cid,'voucher_id'=>$row['_id']])){$this->s->insert('shop_voucher_claims',['chain_id'=>$chain,'customer_id'=>$cid,'voucher_id'=>$row['_id'],'issued_by_admin'=>true]);$this->s->notify($cid,$chain,'voucher:'.$row['_id'].':issued','Bạn được cấp ưu đãi '.$row['name'],'/shop/offers');}return CommerceStore::present($row);
        });
    }
    public function status(Request $r,string $chain,string $kind,string $id): array
    {
        $d=$r->validate(['status'=>'required|in:draft,scheduled,active,paused,ended']);return $this->s->transaction(function()use($r,$chain,$kind,$id,$d){$this->s->admin($r,$chain,null,true);$p=$this->s->find($this->name($kind),$id);abort_unless($p&&$p['chain_id']===$chain,404);return CommerceStore::present($this->s->update($this->name($kind),$p,$d));});
    }
    private function report(string $kind,array $p): array
    {
        $claims=$kind==='vouchers'?$this->s->rows('shop_voucher_claims',['voucher_id'=>$p['_id']],['id_sort'=>1],100000):[];$rows=$this->s->rows($kind==='campaigns'?'shop_campaign_redemptions':'shop_voucher_redemptions',['promotion_id'=>$p['_id']],['id_sort'=>1],100000);$counts=['reserved'=>0,'used'=>0,'released'=>0,'forfeited'=>0];$discount=$revenue=$credit=BigDecimal::zero();$by=[];$orders=[];
        foreach($rows as $row){$counts[$row['state']]++;$o=$this->s->find('shop_orders',$row['order_id']);if(!$o)continue;$orders[]=['order_id'=>$o['_id'],'order_no'=>$o['order_no'],'branch_id'=>$o['branch_id'],'created_at'=>$o['created_at'],'state'=>$row['state'],'discount'=>$row['amount'],'status'=>$o['status']];$bid=$o['branch_id'];$by[$bid]??=['branch_id'=>$bid,'reserved'=>0,'used'=>0,'discount'=>'0.00','revenue'=>'0.00'];if($row['state']==='reserved')$by[$bid]['reserved']++;if($row['state']==='used'){$counts['returned']=($counts['returned']??0)+(int)str_contains($row['reason']??'','return');$discount=$discount->plus((string)$row['amount']);$by[$bid]['used']++;$by[$bid]['discount']=(string)BigDecimal::of($by[$bid]['discount'])->plus((string)$row['amount'])->toScale(2);if($o['invoice_id']){$revenue=$revenue->plus($o['total']);$by[$bid]['revenue']=(string)BigDecimal::of($by[$bid]['revenue'])->plus($o['total'])->toScale(2);foreach($this->s->rows('shop_returns',['order_id'=>$o['_id'],'status'=>'received']) as $ret)$credit=$credit->plus((string)$ret['credit_amount']);}}}
        return $counts+['issued'=>count(array_filter($claims,fn($c)=>$c['issued_by_admin']??false)),'saved'=>count($claims),'discount_on_posted_orders'=>(string)$discount->toScale(2),'posted_invoice_revenue'=>(string)$revenue->toScale(2),'return_credit_on_orders'=>(string)$credit->toScale(2),'by_branch'=>array_values($by),'orders'=>CommerceStore::present($orders)];
    }
    public function wallet(Request $r,string $chain,?string $id=null): array
    {
        $c=$this->s->customer($r);$this->s->settings($chain);if($id!==null)$this->s->transaction(function()use($c,$chain,$id){$p=$this->s->find('shop_vouchers',$id);abort_unless($p&&$p['chain_id']===$chain&&$p['status']!=='draft'&&(!$p['customer_ids']||in_array($c['_id'],$p['customer_ids'],true)),404);if(!$this->s->first('shop_voucher_claims',['customer_id'=>$c['_id'],'voucher_id'=>$id])){$this->s->insert('shop_voucher_claims',['chain_id'=>$chain,'customer_id'=>$c['_id'],'voucher_id'=>$id,'issued_by_admin'=>false]);$this->s->notify($c['_id'],$chain,'voucher:'.$id.':saved','Đã lưu ưu đãi '.$p['name'],'/shop/offers');}});
        $items=[];foreach($this->s->rows('shop_vouchers',['chain_id'=>$chain,'status'=>['$ne'=>'draft']],['id_sort'=>-1],1000) as $p){if($p['customer_ids']&&!in_array($c['_id'],$p['customer_ids'],true))continue;$state=$this->promos->walletState($p,$chain,$c);$safe=array_intersect_key($p,array_flip(['_id','code','name','description','banner','starts_at','ends_at','kind','value','maximum_discount','minimum_order','minimum_quantity','product_ids','category_ids','branch_ids','audience','season_key','allow_auto','allow_other_vouchers']));$safe['availability']=$state;$safe['saved']=$this->s->first('shop_voucher_claims',['customer_id'=>$c['_id'],'voucher_id'=>$p['_id']])!==null;$safe['history']=$this->s->rows('shop_voucher_redemptions',['customer_id'=>$c['_id'],'voucher_id'=>$p['_id']],['id_sort'=>-1],100);foreach($safe['history'] as &$h)unset($h['snapshot']);unset($h);$items[]=$safe;}return CommerceStore::present($items);
    }
}
